export type ResourceGroupId = "report" | "recover" | "learn";

export type ResourceLink = {
  id: string;
  name: string;
  whenUseful: string;
  href: string;
  linkLabel: string;
};

export type ResourceGroup = {
  id: ResourceGroupId;
  title: string;
  links: readonly ResourceLink[];
};

